 83→  const blob = new Blob([sample], { type: "text/csv" });
 84→  const url = URL.createObjectURL(blob);
 85→  const a = document.createElement("a");
 86→  a.href = url;
 87→  a.download = "sample-zip-codes.csv";
 88→  a.click();
 89→  URL.revokeObjectURL(url);
