177→
178→  if (intent === "delete") {
179→    const id = String(formData.get("id"));
180→    try {
181→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
182→      if (!existing) return { error: "Zip code not found." };
183→      await db.zipCode.delete({ where: { id } });
184→      return { success: true, action: "deleted" };
185→    } catch {
186→      return { error: "Failed to delete zip code." };
187→    }
188→  }
189→
190→  if (intent === "update") {
191→    const id = String(formData.get("id"));
192→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
193→    const label = String(formData.get("label") || "").trim();
194→    const zone = String(formData.get("zone") || "").trim();
195→    const message = String(formData.get("message") || "").trim();
196→    const eta = String(formData.get("eta") || "").trim();
197→    const type = String(formData.get("type") || "allowed");
198→    const isActive = formData.get("isActive") === "true";
199→    const codAvailable =
200→      formData.get("codAvailable") === "true"
201→        ? true
202→        : formData.get("codAvailable") === "false"
203→          ? false
204→          : null;
205→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
206→
207→    if (!zipCode) return { error: "Zip code is required." };
208→
209→    try {
210→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
211→      if (!existing) return { error: "Zip code not found." };
212→      await db.zipCode.update({
213→        where: { id },
214→        data: {
215→          zipCode,
216→          label: label || null,
217→          zone: zone || null,
218→          message: message || null,
219→          eta: eta || null,
220→          type,
221→          isActive,
222→          codAvailable,
223→          returnPolicy,
224→        },
