228→      return { error: `Failed to update zip code "${zipCode}". It may already exist.` };
229→    }
230→  }
231→
232→  if (intent === "toggle") {
233→    const id = String(formData.get("id"));
234→    const isActive = formData.get("isActive") === "true";
235→    try {
236→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
237→      if (!existing) return { error: "Zip code not found." };
238→      await db.zipCode.update({
239→        where: { id },
240→        data: { isActive: !isActive },
241→      });
242→      return { success: true, action: "toggled" };
243→    } catch {
244→      return { error: "Failed to toggle zip code status." };
245→    }
246→  }
247→
248→  if (intent === "check") {
249→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
250→    try {
251→      const found = await db.zipCode.findUnique({
252→        where: { shop_zipCode: { shop, zipCode } },
253→      });
