255→      return { checkResult: { found: true, zipCode, record: found } };
256→    } catch {
257→      return { error: "Failed to check zip code." };
258→    }
259→  }
260→
261→  if (intent === "bulk-import") {
262→    const csvData = String(formData.get("csvData") || "");
263→    if (!csvData.trim()) return { error: "No CSV data provided." };
264→
265→    const subscription = await getShopSubscription(shop);
266→    const limits = PLAN_LIMITS[subscription.planTier];
267→
268→    if (!limits.csvImport) {
269→      const upgradeTarget =

270→        subscription.planTier === "free" ? "Starter" : "Pro";
271→      return {
272→        error: `CSV import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to import zip codes via CSV.`,
273→        upgradeRequired: true,
274→      };
275→    }
276→
277→    const lines = csvData
278→      .split("\n")
279→      .map((l) => l.trim())
280→      .filter((l) => l.length > 0);
281→
282→    // Skip header row if present
283→    const startIdx =
284→      lines.length > 0 &&
285→      lines[0].toLowerCase().includes("zip")
286→        ? 1
287→        : 0;
288→
289→    const currentCount = await db.zipCode.count({ where: { shop } });
290→    let imported = 0;
291→    let skipped = 0;
292→    const errors: string[] = [];
293→
294→    for (let i = startIdx; i < lines.length; i++) {
295→      const cols = parseCsvRow(lines[i]);
296→      const zipCode = (cols[0] || "").toUpperCase();
297→      if (!zipCode) continue;
298→
299→      const zone = cols[1] || null;
300→      const type = (cols[2] || "allowed").toLowerCase() === "blocked" ? "blocked" : "allowed";
301→      const message = cols[3] || null;
302→      const eta = cols[4] || null;
303→      const codRaw = (cols[5] || "").toLowerCase().trim();
304→      const codAvailable =
305→        codRaw === "yes" || codRaw === "true"
306→          ? true
307→          : codRaw === "no" || codRaw === "false"
308→            ? false
309→            : null;
310→      const returnPolicy = cols[6] || null;
311→
312→      if (type === "blocked" && !limits.allowBlocked) {
313→        skipped++;
314→        continue;
315→      }
316→
317→      if (
318→        limits.maxZipCodes < UNLIMITED &&
319→        currentCount + imported >= limits.maxZipCodes
320→      ) {
321→        const upgradeTarget =
322→          subscription.planTier === "free" ? "Starter" : "Pro";
323→        errors.push(
324→          `Reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
325→        );
326→        break;
327→      }
328→
329→      try {
330→        await db.zipCode.upsert({
331→          where: { shop_zipCode: { shop, zipCode } },
332→          create: {
333→            shop,
334→            zipCode,
335→            zone,
336→            type,
337→            message,
338→            eta,
339→            codAvailable,
340→            returnPolicy,
341→          },
342→          update: {
343→            zone: zone ?? undefined,
344→            type,
345→            message: message ?? undefined,
346→            eta: eta ?? undefined,
347→            codAvailable,
348→            returnPolicy: returnPolicy ?? undefined,
349→          },
350→        });
351→        imported++;
352→      } catch {
353→        skipped++;
354→      }
355→    }
356→
357→    return {
358→      success: true,
359→      action: "bulk-import",
360→      imported,
361→      skipped,
362→      errors,
363→    };
364→  }
365→
366→  if (intent === "export") {
367→    const subscription = await getShopSubscription(shop);
368→    const limits = PLAN_LIMITS[subscription.planTier];
369→
370→    if (!limits.csvExport) {
371→      return {
372→        error: `CSV export is not available on the ${limits.label} plan. Upgrade to Pro or Ultimate to export your zip codes.`,
