417→    } catch {
418→      return { error: "Failed to delete selected zip codes." };
419→    }

420→  }
421→
422→  if (intent === "range-import") {
423→    const startZip = String(formData.get("startZip") || "").trim().toUpperCase();
424→    const endZip = String(formData.get("endZip") || "").trim().toUpperCase();
425→    const zone = (formData.get("zone") as string | null) || null;
426→    const type = (formData.get("type") as string) === "blocked" ? "blocked" : "allowed";
427→    const message = (formData.get("message") as string | null) || null;
428→    const eta = (formData.get("eta") as string | null) || null;
429→
430→    // Validate: must be 5-digit numeric zips
431→    const ZIP_RE = /^\d{5}$/;
432→    if (!ZIP_RE.test(startZip) || !ZIP_RE.test(endZip)) {
433→      return { error: "ZIP range import only supports 5-digit US ZIP codes (e.g., 10001)." };
434→    }
435→
436→    const start = parseInt(startZip, 10);
437→    const end = parseInt(endZip, 10);
438→
439→    if (end < start) {
440→      return { error: "End ZIP must be greater than or equal to Start ZIP." };
441→    }
442→
443→    const rangeSize = end - start + 1;
444→    const MAX_RANGE = 500;
445→    if (rangeSize > MAX_RANGE) {
446→      return { error: `Range too large. Maximum ${MAX_RANGE} zip codes per import (got ${rangeSize}).` };
447→    }
448→
449→    // Check plan limits
450→    const subscription = await getShopSubscription(shop);
451→    const limits = PLAN_LIMITS[subscription.planTier];
452→
453→    if (!limits.csvImport) {
454→      const upgradeTarget =
455→        subscription.planTier === "free" ? "Starter" : "Pro";
456→      return {
457→        error: `ZIP range import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to use bulk import features.`,
458→        upgradeRequired: true,
459→      };
460→    }
461→
462→    if (type === "blocked" && !limits.allowBlocked) {
463→      return {
464→        error: "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
465→        upgradeRequired: true,
466→      };
467→    }
468→
469→    const currentCount = await db.zipCode.count({ where: { shop } });
470→    if (limits.maxZipCodes < UNLIMITED && currentCount + rangeSize > limits.maxZipCodes) {
471→      const upgradeTarget =
472→        subscription.planTier === "free" ? "Starter" : "Pro";
473→      return {
474→        error: `This range would exceed your ${limits.label} plan limit of ${limits.maxZipCodes} zip codes. You have ${limits.maxZipCodes - currentCount} slots remaining. Upgrade to ${upgradeTarget} for a higher limit.`,
475→        upgradeRequired: true,
476→      };
477→    }
478→
479→    // Generate and upsert all zips in range
480→    let imported = 0;
481→    for (let i = start; i <= end; i++) {
482→      const zipCode = String(i).padStart(5, "0");
483→      try {
484→        await db.zipCode.upsert({
485→          where: { shop_zipCode: { shop, zipCode } },
486→          create: { shop, zipCode, zone: zone ?? undefined, type, message: message ?? undefined, eta: eta ?? undefined },
487→          update: { zone: zone ?? undefined, type, message: message ?? undefined, eta: eta ?? undefined },
488→        });
489→        imported++;
490→      } catch {
491→        // skip individual errors
492→      }
493→    }
494→
495→    return { success: true, action: "range-import", imported, total: rangeSize };
496→  }
497→
498→  return null;
499→};
