217→
218→    if (!id) return { error: "Missing zip code ID." };
219→    if (!zipCode) return { error: "Zip code is required." };
220→
221→    try {
222→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
223→      if (!existing) return { error: "Zip code not found." };
224→      // Update scoped to verified id+shop record
225→      await db.zipCode.update({
226→        where: { id: existing.id },
227→        data: {
228→          zipCode,
229→          label: label || null,
230→          zone: zone || null,
231→          message: message || null,
232→          eta: eta || null,
233→          type,
234→          isActive,
235→          codAvailable,
236→          returnPolicy,
237→        },
