248→
249→  if (intent === "toggle") {
250→    const id = String(formData.get("id") ?? "");
251→    if (!id) return { error: "Missing zip code ID." };
252→    const isActive = formData.get("isActive") === "true";
253→    try {
254→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
255→      if (!existing) return { error: "Zip code not found." };
