266→
267→  if (intent === "check") {
268→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
269→    try {
270→      const found = await db.zipCode.findUnique({
271→        where: { shop_zipCode: { shop, zipCode } },
272→      });
