279→
280→  if (intent === "bulk-import") {
281→    const csvData = String(formData.get("csvData") || "");
282→    if (!csvData.trim()) return { error: "No CSV data provided." };
283→
284→    try {
285→      const subscription = await getShopSubscription(shop);
286→      const limits = PLAN_LIMITS[subscription.planTier];
287→
288→      if (!limits.csvImport) {
289→        const upgradeTarget =
290→          subscription.planTier === "free" ? "Starter" : "Pro";
291→        return {
292→          error: `CSV import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to import zip codes via CSV.`,
293→          upgradeRequired: true,
294→        };
295→      }
296→
297→      const lines = csvData
298→        .split("\n")
299→        .map((l) => l.trim())
300→        .filter((l) => l.length > 0);
301→
302→      // Skip header row if present
303→      const startIdx =
304→        lines.length > 0 &&
305→        lines[0].toLowerCase().includes("zip")
306→          ? 1
307→          : 0;
308→
309→      const currentCount = await db.zipCode.count({ where: { shop } });
310→      let imported = 0;
311→      let skipped = 0;
312→      const errors: string[] = [];
313→
314→      for (let i = startIdx; i < lines.length; i++) {
315→        const cols = parseCsvRow(lines[i]);
316→        const zipCode = (cols[0] || "").toUpperCase().trim();
317→        if (!zipCode) continue;
318→
319→        const zone = cols[1] || null;
320→        // Sanitize: only "blocked" is accepted as an alternative to "allowed"
321→        const type = (cols[2] || "").toLowerCase().trim() === "blocked" ? "blocked" : "allowed";
322→        const message = cols[3] || null;
323→        const eta = cols[4] || null;
324→        const codRaw = (cols[5] || "").toLowerCase().trim();
325→        const codAvailable =
326→          codRaw === "yes" || codRaw === "true"
327→            ? true
328→            : codRaw === "no" || codRaw === "false"
329→              ? false
330→              : null;
331→        const returnPolicy = cols[6] || null;
332→
333→        if (type === "blocked" && !limits.allowBlocked) {
334→          skipped++;
335→          continue;
336→        }
337→
338→        if (
339→          limits.maxZipCodes < UNLIMITED &&
340→          currentCount + imported >= limits.maxZipCodes
341→        ) {
342→          const upgradeTarget =
343→            subscription.planTier === "free" ? "Starter" : "Pro";
344→          errors.push(
345→            `Reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
346→          );
