348→        }
349→
350→        try {
351→          await db.zipCode.upsert({
352→            where: { shop_zipCode: { shop, zipCode } },
353→            create: {
354→              shop,
355→              zipCode,
356→              zone,
357→              type,
358→              message,
359→              eta,
360→              codAvailable,
361→              returnPolicy,
362→            },
363→            update: {
364→              zone: zone ?? undefined,
365→              type,
366→              message: message ?? undefined,
367→              eta: eta ?? undefined,
368→              codAvailable,
369→              returnPolicy: returnPolicy ?? undefined,
370→            },
371→          });
372→          imported++;
373→        } catch {
374→          skipped++;
375→        }
376→      }
377→
378→      return {
379→        success: true,
380→        action: "bulk-import",
381→        imported,
382→        skipped,
383→        errors,
384→      };
385→    } catch {
386→      return { error: "Failed to import zip codes. Please try again." };
387→    }
388→  }
389→
390→  if (intent === "export") {
391→    try {
392→      const subscription = await getShopSubscription(shop);
393→      const limits = PLAN_LIMITS[subscription.planTier];
394→
395→      if (!limits.csvExport) {
396→        return {
397→          error: `CSV export is not available on the ${limits.label} plan. Upgrade to Pro or Ultimate to export your zip codes.`,
398→          upgradeRequired: true,
399→        };
400→      }
401→
402→      const zipCodes = await db.zipCode.findMany({
403→        where: { shop },
404→        orderBy: { createdAt: "desc" },
405→      });
406→
407→      const header = "Zip Code,Zone,Status,Message,ETA,Active,COD,Return Policy";
408→      const rows = zipCodes.map(
409→        (z) =>
410→          `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}","${z.codAvailable === true ? "Yes" : z.codAvailable === false ? "No" : ""}","${z.returnPolicy || ""}"`,
411→      );
412→      const csv = [header, ...rows].join("\n");
413→
414→      return { success: true, action: "export", csv };
415→    } catch {
416→      return { error: "Failed to export zip codes." };
417→    }
418→  }
419→
420→  if (intent === "bulk-delete") {
421→    const idsRaw = String(formData.get("ids") || "");
422→    const ids = idsRaw
423→      .split(",")
424→      .map((id) => id.trim())
425→      .filter(Boolean);
426→
427→    if (ids.length === 0) return { error: "No zip codes selected." };
428→
429→    // Guard: cap to a reasonable max to prevent abuse
430→    if (ids.length > 5000) {
431→      return { error: "Too many zip codes selected at once. Please select fewer than 5000." };
432→    }
433→
434→    try {
435→      // Delete only records that belong to this shop — always shop-scoped.
436→      // We do NOT reject if some IDs are missing (race condition / already deleted)
437→      // — instead we report how many were actually deleted.
438→      const result = await db.zipCode.deleteMany({
439→        where: { id: { in: ids }, shop },
440→      });
441→      return { success: true, action: "bulk-delete", deleted: result.count };
442→    } catch {
443→      return { error: "Failed to delete selected zip codes." };
444→    }
445→  }
446→
447→  if (intent === "range-import") {
448→    const startZip = String(formData.get("startZip") || "").trim().toUpperCase();
449→    const endZip = String(formData.get("endZip") || "").trim().toUpperCase();
450→    const zone = (formData.get("zone") as string | null) || null;
451→    // Sanitize type — only accept known values, default to "allowed"
452→    const type = String(formData.get("type") || "") === "blocked" ? "blocked" : "allowed";
453→    const message = (formData.get("message") as string | null) || null;
454→    const eta = (formData.get("eta") as string | null) || null;
455→
456→    // Validate: must be 5-digit numeric zips
457→    const ZIP_RE = /^\d{5}$/;
458→    if (!ZIP_RE.test(startZip) || !ZIP_RE.test(endZip)) {
459→      return { error: "ZIP range import only supports 5-digit US ZIP codes (e.g., 10001)." };
460→    }
461→
462→    const start = parseInt(startZip, 10);
463→    const end = parseInt(endZip, 10);
464→
465→    if (end < start) {
466→      return { error: "End ZIP must be greater than or equal to Start ZIP." };
467→    }
468→
469→    const rangeSize = end - start + 1;
470→    const MAX_RANGE = 500;
471→    if (rangeSize > MAX_RANGE) {
472→      return { error: `Range too large. Maximum ${MAX_RANGE} zip codes per import (got ${rangeSize}).` };
473→    }
474→
475→    try {
476→      // Check plan limits
477→      const subscription = await getShopSubscription(shop);
478→      const limits = PLAN_LIMITS[subscription.planTier];
479→
480→      if (!limits.csvImport) {
481→        const upgradeTarget =
482→          subscription.planTier === "free" ? "Starter" : "Pro";
483→        return {
484→          error: `ZIP range import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to use bulk import features.`,
485→          upgradeRequired: true,
486→        };
487→      }
488→
489→      if (type === "blocked" && !limits.allowBlocked) {
490→        return {
491→          error: "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
492→          upgradeRequired: true,
493→        };
494→      }
495→
496→      const currentCount = await db.zipCode.count({ where: { shop } });
497→      if (limits.maxZipCodes < UNLIMITED && currentCount + rangeSize > limits.maxZipCodes) {
498→        const upgradeTarget =
499→          subscription.planTier === "free" ? "Starter" : "Pro";
500→        return {
501→          error: `This range would exceed your ${limits.label} plan limit of ${limits.maxZipCodes} zip codes. You have ${limits.maxZipCodes - currentCount} slots remaining. Upgrade to ${upgradeTarget} for a higher limit.`,
502→          upgradeRequired: true,
503→        };
504→      }
505→
506→      // Build all zip records for the range
507→      const zipRecords = Array.from({ length: rangeSize }, (_, i) => ({
508→        shop,
509→        zipCode: String(start + i).padStart(5, "0"),
510→        zone: zone ?? undefined,
511→        type,
512→        message: message ?? undefined,
513→        eta: eta ?? undefined,
514→      }));
515→
516→      // Use createMany with skipDuplicates — much faster than N sequential upserts.
517→      // For existing records (skipDuplicates), we do a follow-up updateMany to refresh
518→      // zone/type/message/eta so the import always reflects the submitted values.
519→      const created = await db.zipCode.createMany({
520→        data: zipRecords,
521→        skipDuplicates: true,
522→      });
523→
524→      // Update any already-existing records in the range to apply the new values
525→      await db.zipCode.updateMany({
526→        where: {
527→          shop,
528→          zipCode: { in: zipRecords.map((r) => r.zipCode) },
529→        },
530→        data: {
531→          zone: zone ?? undefined,
532→          type,
533→          message: message ?? undefined,
534→          eta: eta ?? undefined,
535→        },
536→      });
537→
538→      return { success: true, action: "range-import", imported: created.count, total: rangeSize };
539→    } catch {
540→      return { error: "Failed to import ZIP code range. Please try again." };
541→    }
542→  }
